import json
from pathlib import Path
OUT=Path(__file__).resolve().parent.parent/'data'
def mc(q,opts,a,e):return dict(type='choice',question=q,options=opts.split('|'),answer=a,explanation=e)
def sh(q,a,e):return dict(type='short',question=q,answer=a,explanation=e,rubric=[a,'说明条件或推理过程'])
def ex(q,steps,a):return dict(question=q,steps=steps.split('|'),answer=a)
def unit(sub,n,title,intro,sections,formulas,examples,act,quiz,sim,tags):
 return dict(id=f'{sub}-{n:02}',subject=sub,chapter=f'专题 {n:02}',title=title,term='复习' if sub=='biology' else '拓展',category='复习' if sub=='biology' else '拓展',intro=intro,periods='1–2课时（建议）',goals=[f'解释“{sections[0][0]}”的核心概念',f'用证据说明“{sections[1][0]}”',f'完成“{act[0]}”并说清模型的限制'],sections=[dict(title=h,body=b) for h,b in sections],formulas=[dict(text=t,note=n) for t,n in formulas],examples=examples,activity=dict(title=act[0],materials=act[1],steps=act[2].split('|'),recordHeaders=['改变的条件','观察或计算','证据','解释'],conclusion=act[3],safety=act[4]),mistakes=tags[-3:],quiz=quiz,sim=sim,tags=tags[:3])
b=[]
b.append(unit('biology',1,'细胞、DNA与生命结构','为什么一个细胞能保存并传递生命信息？',[
('细胞的结构与功能','细胞是生物体结构和功能的基本单位，病毒没有细胞结构。细胞膜控制物质进出；细胞质是许多生命活动进行的场所；细胞核中有重要遗传物质。常见植物细胞还具有细胞壁、液泡，叶片绿色部位细胞常有叶绿体，不能据“植物细胞”断言每个细胞都有叶绿体。'),
('DNA与细胞分裂','染色体主要由DNA和蛋白质组成，DNA上具有遗传效应的片段可称为基因。细胞分裂前遗传物质先复制，再分配到子细胞。在初中常见的体细胞分裂模型中，子细胞与原细胞的染色体数目相同；细胞生长主要增加体积，分裂主要增加数目。'),
('观察与模型','显微镜放大倍数等于目镜与物镜倍数的乘积；放大倍数增加，通常视野变小，可看到的细胞数变少。装片、染色与图示都可能改变观察结果，图中颜色并不总等于细胞天然颜色。模型用于表现结构关系，不代表真实大小比例。')],[('总放大倍数=目镜倍数×物镜倍数','两者倍数相乘'),('1→2→4→8','理想同步分裂示意，不表示实际固定时间')],[ex('10倍目镜配40倍物镜，总放大倍数是多少？','认清两个镜头倍数|10×40=400','400倍'),ex('一个体细胞连续分裂3次，共得到多少个细胞？','每次细胞数量加倍|依次为2、4、8','8个，假设每轮所有细胞均完成分裂')],['纸片模拟遗传物质分配','双色纸条、纸环、记录纸','用纸条表示一套染色体|复制每条纸条再将两套分开|比较分裂前后每个细胞内的数量','分裂前先复制，使子细胞能获得与母细胞相同数目的染色体。','纸条颜色、形状和大小均为示意。'],[
mc('没有细胞结构的是哪一种？','酵母菌|细菌|病毒|洋葱',2,'病毒无细胞结构，其余有细胞结构。'),mc('显微镜目镜5倍、物镜20倍，总倍数是多少？','25倍|100倍|15倍|400倍',1,'5×20=100。'),mc('细胞分裂主要增加什么？','细胞数目|每个细胞体积|每个细胞染色体数|每个细胞液泡大小',0,'分裂产生更多细胞；生长主要增大体积。'),mc('下列说法正确的是哪一个？','每个植物细胞都有叶绿体|DNA只存在于植物中|染色体只由蛋白质构成|基因与遗传信息有关',3,'基因是具有遗传效应的DNA片段；其余表述过于绝对或错误。'),sh('为何分裂前要复制遗传物质？','为两个子细胞分别提供相应遗传物质。','仅将未复制的一套平均分开会导致每个子细胞获得的数量减少。'),sh('放大倍数增加后，视野中的细胞数通常如何变化？','通常变少。','放大倍数增大使可观察范围变小。')],'cells',['细胞','DNA','显微镜','病毒不是由细胞构成。','植物根部许多细胞没有叶绿体。','分裂前的复制不等于子细胞染色体数加倍。']))
b.append(unit('biology',2,'光合作用与呼吸作用','植物白天制造有机物，晚上就停止生命活动了吗？',[
('光合作用','绿色植物利用光能，在叶绿体中把二氧化碳和水转变成有机物，并释放氧气。它使无机物转变为有机物，把光能储存在有机物中。探究需要控制光照、二氧化碳等变量；实验前暗处理旨在消耗叶片原有淀粉，碘液用于检验淀粉。'),
('呼吸作用','细胞通过呼吸作用分解有机物、释放能量，供生命活动利用。初中常讨论有氧呼吸：有机物与氧反应生成二氧化碳和水并释放能量。植物的活细胞白天和夜晚一般都进行呼吸作用，种子萌发同样需要释放能量。'),
('气体变化与控制变量','植物在光下同时进行光合作用和呼吸作用，外界观测到的是二者共同造成的净变化。看到气泡不能仅凭外观判定其气体种类。研究光的作用应设置有光和遮光的对照，其他条件保持一致；实验结论应与实际控制条件相符。')],[('光合作用：CO₂+水 → 有机物+O₂','文字关系式，需光和叶绿体；不是已配平的化学方程式'),('有氧呼吸：有机物+O₂ → CO₂+水+能量','能量不是一种物质')],[ex('植物夜晚不能进行光合作用，是否仍会消耗有机物？','夜晚缺少光照，光合作用受限|活细胞仍进行呼吸作用','会，呼吸作用仍消耗有机物并释放能量'),ex('检验叶片遇光是否产生淀粉，为什么先暗处理？','叶片可能已含淀粉|先消耗原有淀粉，减少干扰','使检验结果更能反映实验期间新形成的淀粉')],['设计叶片遮光对照','纸上叶片模型、黑纸、实验记录卡','提出光是否为必要条件|在同一叶片设见光和遮光部分|写出暗处理、脱色、碘液检验及预期对照','见光部分出现淀粉证据，需在其他条件可比时解释。','酒精脱色涉及加热，只由教师按规范水浴演示；本活动可仅作方案设计。'],[
mc('光合作用主要把什么能转化为化学能？','声能|光能|电能|核能',1,'植物通过光合作用储存光能。'),mc('植物通常在什么时候进行呼吸作用？','只在白天|只在夜晚|只在开花时|白天和夜晚',3,'活细胞生命活动需要持续获得能量。'),mc('检验淀粉常用什么试剂？','碘液|食盐水|蒸馏水|稀盐酸',0,'淀粉遇碘液显蓝色，可作为实验依据。'),mc('探究光照作用时，最重要的设计是什么？','一次改变所有条件|只观察一片没有处理的叶子|设见光和遮光对照|只看叶片颜色',2,'对照与控制变量帮助判断因果关系。'),sh('光照下叶片同时进行哪两种相关作用？','光合作用与呼吸作用。','看到的气体净变化取决于二者强弱。'),sh('为什么不能把呼吸作用简单说成吸气和呼气？','细胞呼吸是分解有机物并释放能量的过程。','人体吸气呼气是气体交换的环节，与细胞内反应不同。')],'photosynthesis',['叶绿体','光合作用','呼吸','植物白天也呼吸。','光合作用与呼吸作用不是同一过程的机械反向播放。','气泡本身不能证明气体一定是氧气。']))
b.append(unit('biology',3,'遗传规律与变异','父母相同的表现，会不会生出不同表现的后代？',[
('基因与性状','性状是生物可观察的形态、生理等特征。基因通过影响相关物质的合成参与性状表达，但环境也会影响表现。成对基因中，A和a可表示一对显隐性等位基因；在单基因完全显性模型下，AA与Aa表现显性，aa表现隐性。'),
('分离与概率','生殖过程中，亲代成对基因通过生殖细胞传递，后代从双亲各获得一个。Aa与Aa组合可列出AA、Aa、aA、aa，基因型比例为1∶2∶1，显性与隐性表现概率为3∶1。这是每次组合的概率，不保证每四个后代恰有一个隐性。'),
('变异与适用范围','遗传物质变化造成的变异可能遗传；仅由环境改变且遗传物质未变造成的变化，通常不能按相同方式遗传。人的身高、肤色等涉及多个基因及环境，不能套用简单豌豆式单基因计算。禁止用性状判断人的价值或能力。')],[('Aa×Aa → AA、Aa、Aa、aa','仅用于单基因完全显性模型'),('P(aa)=1/4','等可能配子、随机结合的简化模型')],[ex('Aa与aa杂交，隐性后代概率是多少？','第一方可提供A或a|第二方只提供a|组合为Aa和aa','1/2'),ex('AA与aa组合，子代基因型是什么？','双方分别只提供A和a|每个子代组合为Aa','全部为Aa，表现显性（模型条件下）')],['用卡片模拟基因组合','A、a卡片各两套','两位同学各准备A、a卡|每轮各随机取一张并放回|记录20轮再与另一组数据合并','次数增加后频率有机会接近理论概率，小样本可明显偏离。','仅为概率模型，不用于判断真实个人遗传风险。'],[
mc('完全显性模型中，aa表现什么性状？','隐性|显性|无法形成个体|两种各一半',0,'两个隐性等位基因组合表现隐性。'),mc('Aa×Aa得到AA的概率为多少？','1|1/2|1/4|3/4',2,'四种等可能组合中AA占一种。'),mc('AA×aa的子代基因型是什么？','AA|Aa|aa|AA和aa',1,'子代分别从双亲获得A和a。'),mc('以下说法正确的是？','每四个后代必有一个aa|性状完全不受环境影响|所有性状都只受一个基因控制|性状可能同时受遗传与环境影响',3,'复杂性状需要考虑多种因素。'),sh('为何连续出生三个显性后代不否定隐性概率为1/4？','概率并不保证小样本中严格按比例出现。','不同组合是随机事件，次数少时偏差正常。'),sh('Aa×aa中Aa和aa的理论比是多少？','1∶1。','A、a两种配子分别与a结合得到Aa、aa。')],'genetics',['基因','遗传','概率','显性不等于优良。','每次事件的概率不等于少量后代的固定数量比例。','真实复杂性状不可直接套用单基因模型。']))
b.append(unit('biology',4,'生态系统与生物多样性','一条食物链中的某种生物减少，会牵动哪些关系？',[
('生态系统组成','生态系统由一定区域内的生物与非生物环境组成。生产者把无机物转化为有机物，消费者直接或间接利用其他生物获取有机物，分解者把有机物分解，促进物质循环。细菌与真菌中许多属于分解者，但并非所有细菌都只有分解作用。'),
('食物链与能量流动','食物链中的箭头从被捕食者指向捕食者，表示物质和能量的传递方向。初中常见食物链从生产者开始，不把阳光和分解者写进捕食食物链。能量流动通常单向且逐级递减；物质可以在系统中循环，能量并不循环利用。'),
('稳定与保护','生态系统有一定自我调节能力，但有界限。减少某一物种可能改变多个种群，不能仅凭一条线预测所有数量变化。保护生物多样性包括保护遗传多样性、物种多样性和生态系统多样性，保护栖息地具有重要意义。')],[('草 → 食草昆虫 → 青蛙 → 蛇','箭头指向摄食者'),('能量逐级递减','本课不把固定传递效率作为普遍常数')],[ex('草、兔、狐之间怎样画一条食物链？','从生产者草开始|兔吃草，狐吃兔|箭头由食物指向消费者','草→兔→狐'),ex('一片森林仅列出树木、鸟类和昆虫，是否构成完整生态系统描述？','还要包含其他生物与非生物环境|还需注意分解者等生态功能','描述不完整，还应考虑水、空气、土壤等环境与完整生物组成')],['校园微生境观察','记录本、放大镜（可选）','划定小范围观察区域|记录生物与非生物因素|用观察证据画关系图|写出至少一种保护建议','生态系统研究要同时关注生物联系与环境条件。','不捕捉、不采食未知生物，不破坏栖息地。'],[
mc('捕食食物链通常从什么开始？','分解者|阳光|生产者|顶级捕食者',2,'食物链的生物起点通常为生产者。'),mc('草→兔中的箭头主要表示什么？','兔变成草|物质和能量由草传向兔|草追赶兔|数量一定相等',1,'箭头从被吃的生物指向摄食者。'),mc('哪项属于非生物因素？','水分|草|鸟|蘑菇',0,'水分是环境因素，不是生物。'),mc('生态系统自我调节能力有什么特点？','无限强|完全不存在|能消除一切污染|有一定限度',3,'扰动过大可超出其调节能力。'),sh('分解者对生态系统有什么重要作用？','分解有机物，促进物质循环。','让部分物质以无机形式回到环境，供生产者利用。'),sh('能量流动与物质循环有何区别？','能量通常单向流动并逐级递减，物质可循环。','二者不能简单视为同一种循环过程。')],'ecosystem',['生态系统','食物链','多样性','能量不能像物质一样在系统中反复循环。','食物链箭头由被食者指向摄食者。','自我调节能力不是无限的。']))
(OUT/'biology.json').write_text(json.dumps(dict(subject='biology',edition='初中生物复习专题',editionNote='对应初中已学知识的九年级复习补充，不是人教版九年级生物分册。',sources=[dict(title='义务教育课程标准目录',url='https://www.ictr.edu.cn/download_center/ywjy.html')],chapters=b),ensure_ascii=False,indent=2))
a=[]
a.append(unit('astronomy',1,'太阳系与轨道运动','为什么行星绕太阳运行，却不会在一圈以后停下来？',[
('层次与分类','太阳是恒星，地球是绕太阳运行的行星，月球是地球的天然卫星。太阳系包含八颗行星以及卫星、小行星、彗星等。恒星能通过内部过程持续释放能量，行星和卫星的可见光主要来自反射。太阳系只是银河系的一部分。'),('轨道与引力','引力改变天体运动方向，维持轨道运动。理想二体模型中，行星轨道可近似看作椭圆，太阳位于一个焦点；椭圆可以很接近圆。行星到太阳的距离和公转时间有关系，实际多体系统还会受到其他天体影响。'),('比例尺意识','太阳系图常把天体画得过大、距离画得过小，目的是便于辨认。太阳系的天体大小与彼此距离无法在普通屏幕上同时清晰按真实比例展示。使用模型时应分别说明大小比例、距离比例和动画时间比例。')],[('恒星 → 行星 → 卫星','关系示意，箭头不是物体演化顺序')],[ex('把地球标为行星、月球标为恒星，哪里有误？','判断绕谁运行|月球围绕地球运行，主要反射太阳光','月球应标为天然卫星'),ex('模型把1 AU表示为1 m，约5 AU的距离应画多长？','采用同一线性比例尺|5×1 m','约5 m；AU是地日平均距离的尺度单位')],['给太阳系图写比例说明','白纸、尺、轨道示意图','选定距离比例尺|计算几个相对轨道半径|比较按同一比例画天体大小是否清楚','科学示意图的大小、距离和时间常采用不同缩放。','不把模型速度或大小当成真实数值。'],[mc('太阳属于哪一类天体？','恒星|行星|卫星|彗星',0,'太阳是太阳系的恒星。'),mc('月球主要围绕什么公转？','火星|地球|木星|北极星',1,'月球是地球的天然卫星。'),mc('太阳系中目前通常认定有几颗行星？','7|9|8|10',2,'通常采用八行星分类。'),mc('关于教材太阳系示意图，正确的是？','天体大小全部是真实比例|距离全部是真实比例|时间尺度一定真实|可能使用不同缩放比例',3,'示意图优先表达关系，需要查看比例说明。'),sh('引力对轨道运动起什么作用？','改变运动方向，使天体维持绕行。','不能把轨道运动解释成物体完全不受力。'),sh('为何不能根据示意图直接比较地球与太阳的实际距离比例？','示意图可能没有按真实距离比例绘制。','应先查比例尺或明确数值。')],'orbit',['太阳系','行星','轨道','太阳系不是整个宇宙。','月球主要反射太阳光。','图示轨道速度与大小并非真实比例。']))
a.append(unit('astronomy',2,'月相与日月食','每个月都有新月和满月，为什么并非每月都有日食与月食？',[
('月相的形成','月球本身不发可见光，太阳照亮它的一半。随着月球绕地球运动，地球上的观察者看到被照亮部分的比例变化，形成月相。新月与满月大致对应月球在地球和太阳之间、地球在太阳和月球之间的方向关系；普通月相并非地球影子造成。'),('日食与月食','日食发生时，月球位于太阳和地球之间，其影子可能落到地球上；月食发生时，地球在太阳和月球之间，月球进入地球影区。形成食还需要近乎共线及轨道位置等几何条件，仅有新月或满月并不充分。'),('轨道倾角与观察','月球轨道相对地球公转轨道平面有倾角，多数新月和满月时三者不精确对齐。模型若把所有轨道压到同一平面，会错误暗示每月都有食。太阳观测必须使用专门合规设备与指导，普通墨镜不能替代太阳观测滤镜。')],[('日食排列：太阳—月球—地球','还需接近共线等几何条件'),('月食排列：太阳—地球—月球','月球进入地球影区')],[ex('新月时是否一定有日食？','新月给出大致方向关系|轨道倾角可能使影子错开地球','不一定，还须满足对齐条件'),ex('看到半月能否断言地球挡住了半个月球？','月相取决于看到的受光部分|地球影子只与月食有关','不能，普通月相不是地球影子造成的')],['灯与球模拟月相','台灯、小球、固定观察点','用台灯代表太阳|小球绕观察点移动|记录不同位置看到的亮面|倾斜小球运行平面，观察对齐条件','月相与受光视角有关，食还要求恰当对齐。','用台灯即可，不直视太阳；尺寸与轨道不按真实比例。'],[mc('普通月相主要由什么造成？','月球自身发光变化|看到的受光部分变化|每天发生月食|月球大小变化',1,'月球受光面与观察角度的相对关系发生变化。'),mc('日食时中间的天体是哪一个？','月球|地球|太阳|火星',0,'月球处于太阳和地球之间。'),mc('月食时中间的天体是哪一个？','月球|金星|地球|木星',2,'地球的影子遮住月球。'),mc('为什么不每月发生月食？','月球每月消失|地球不产生影子|太阳每月熄灭|轨道倾角使多数满月不精确对齐',3,'轨道倾斜使月球常从影区上方或下方经过。'),sh('日食与月食的排列分别是什么？','日食：日—月—地；月食：日—地—月。','排列只是必要方向关系，还要满足近乎共线等条件。'),sh('月相模型应说明哪一项局限？','天体尺寸、距离和轨道倾角通常被简化。','同平面模型不能准确表示日月食出现频率。')],'eclipse',['月相','日食','月食','月相并非地球影子造成。','新月不一定发生日食。','普通墨镜不能用于直接观测太阳。']))
a.append(unit('astronomy',3,'昼夜、四季与地轴倾斜','如果夏天只是因为靠太阳更近，为什么南北半球季节相反？',[
('昼夜交替','地球近似球体，同一时刻通常只有一半表面被太阳直接照亮。地球自转使各地点交替进入向阳面和背阳面，造成昼夜交替。公转与自转是不同运动：自转是绕地轴转动，公转是绕太阳运行。'),('四季的主要原因','地轴相对公转轨道平面的倾斜，使一年中太阳直射位置和各地白昼长度发生变化。某半球更朝向太阳时，通常太阳高度较大、白昼较长，单位面积接收的太阳能更多，容易形成夏季。南北半球季节相反，不能仅用地日距离解释四季。'),('模型与当地气候','纬度、海陆位置、地形和大气环流等也影响实际气温。示意中的季节与平均受光情况相关，不能用一次气温测量证明四季机制。讨论极昼极夜需要考虑纬度及季节，本专题只进行定性探索。')],[('自转 → 昼夜交替','需考虑球形地球受光'),('地轴倾斜 + 公转 → 四季变化','地轴方向在一年尺度内可近似保持不变')],[ex('北半球夏季时，南半球大致是什么季节？','地轴倾斜使南北半球受光趋势相反|北半球朝向太阳更多','南半球大致为冬季'),ex('将地球模型不倾斜地绕灯移动，能否很好解释真实四季？','该模型忽略主要条件地轴倾斜|不能得到正确的季节受光差异','不能，需要加入地轴倾斜')],['手电照射角度比较','手电、白纸、球体','固定距离照射白纸|比较直照和斜照光斑面积|在球面不同位置重复|说明同样光能分布到不同面积的区别','光线越斜，光能通常分布在更大面积上。','不将强光照向眼睛，模型不能代替真实气象数据。'],[mc('昼夜交替主要与什么有关？','月球自转|地球自转|地球形变|云量变化',1,'地球自转使各地交替进入明暗两侧。'),mc('解释四季的重要条件是？','地轴倾斜|太阳每年熄灭|地球每天变大|月球反光消失',0,'倾斜地轴随地球公转改变季节受光情况。'),mc('南北半球季节通常怎样？','始终相同|都只有冬季|大致相反|随机互换',2,'地轴倾斜导致两半球季节受光趋势相反。'),mc('下列哪项不能单独解释地球四季？','太阳高度变化|昼长变化|地轴倾斜|地日距离变化',3,'距离变化不能解释南北半球季节相反。'),sh('自转与公转如何区分？','自转绕自身地轴；公转绕太阳。','研究对象及所绕轴或中心不同。'),sh('为何斜照时单位面积接收能量通常较少？','同样的光能分布在更大的面积上。','比较应保持光源强度和距离等条件可比。')],'seasons',['四季','自转','地轴','四季不能只用地日距离解释。','太阳高度变化不等于太阳大小变化。','一次天气观测不是季节机制的充分证据。']))
a.append(unit('astronomy',4,'恒星、黑洞与宇宙尺度','看不见黑洞内部，科学家如何研究它？',[
('恒星与星系','恒星是持续释放能量的天体，银河系包含大量恒星、气体与尘埃等。光年是光在真空中一年传播的距离，属于长度单位，不是时间单位。望远镜看到远方天体的光，就在接收它过去发出的信息。'),('黑洞与观测证据','黑洞具有事件视界；越过视界后，连光也无法逃离。它不是无条件吸走整个宇宙的吸尘器。研究者通过附近恒星和气体的运动、吸积物质辐射、引力波等证据研究黑洞。图像中的亮环通常来自周围高温物质，不是黑洞内部发出的光。'),('宇宙膨胀','在足够大的尺度上，星系间空间整体呈膨胀趋势，可用气球表面点间距离增大作类比。这个模型不是说宇宙一定有气球那样的外部空间或表面中心；引力束缚系统也不会简单随膨胀等比例变大。本专题为定性科学阅读。')],[('1光年：光在真空中一年传播的距离','长度单位'),('证据 → 模型 → 新观测检验','模型必须受证据约束')],[ex('“这颗星距我们10光年，因此光走了约10年”是否合理？','光年表示距离|按光在真空中的速度传播计算','可作为简化理解，实际天文距离解释还需模型条件'),ex('黑洞周围有亮环，是否说明光从事件视界内部逃出？','区分内部与外部|周围吸积物质可发光','不是，亮环主要反映周围物质与引力效应')],['伸缩点阵与模型边界','弹性带或纸上比例图、尺','画出三个相隔的点|均匀拉伸或放大间距|比较不同点间距离变化|写出该模型不能表达的现象','比例放大可帮助理解距离变化，但不能当作宇宙真实形状。','拉伸时避免弹回；不把二维模型解释成宇宙全部结构。'],[mc('光年是什么单位？','时间|质量|长度|温度',2,'光年定义为光一年传播的距离。'),mc('黑洞事件视界内部的光能否逃出？','不能|一定可以|只在白天可以|只要光够亮就可以',0,'事件视界是无法向外传出光信号的边界。'),mc('银河系与太阳系的关系是什么？','完全相同|太阳系是银河系的一部分|银河系在地球内部|互不相关',1,'太阳系位于银河系中。'),mc('气球模型的正确用法是什么？','证明宇宙有外壁|证明地球在宇宙中心|证明所有原子都会膨胀|帮助理解距离变化并说明局限',3,'类比能说明部分关系，不能推广全部性质。'),sh('列举一种研究黑洞的间接证据。','周围恒星运动、吸积辐射或引力波。','从可观测效应约束不可直接看见的对象。'),sh('为什么看遥远天体相当于接收过去的信息？','光传播需要时间。','接收到的光在更早时刻已从天体发出。')],'universe',['黑洞','光年','宇宙','光年不是时间单位。','黑洞不是无限距离的吸尘器。','气球类比不证明宇宙有外壁。']))
(OUT/'astronomy.json').write_text(json.dumps(dict(subject='astronomy',edition='九年级科学拓展',editionNote='跨学科拓展，不作为人教版九年级必修目录或中考考纲。',sources=[dict(title='NASA：月相',url='https://science.nasa.gov/moon/moon-phases/'),dict(title='NASA：日食与月食',url='https://science.nasa.gov/moon/eclipses/'),dict(title='NASA：黑洞',url='https://science.nasa.gov/universe/black-holes/')],chapters=a),ensure_ascii=False,indent=2))
c=[]
c.append(unit('coding',1,'算法与流程控制','怎样把“我知道怎么做”写成别人也能执行的步骤？',[
('算法的表达','算法是解决特定问题的一组明确步骤。输入、输出、步骤顺序、终止条件要说清楚，可以用自然语言、流程图或伪代码表达。好算法不仅产生预期结果，还应能处理边界情况；“一直做直到成功”若没有可判断条件就不够明确。'),('顺序、分支与循环','顺序结构依次执行步骤；分支依据条件选择路径；循环重复执行一段过程。求1到n的和时，需要设置初始和为0、计数器从1开始、累加后更新计数器，并明确停止位置。少更新计数器可能导致无限循环。'),('测试与调试','测试要包括普通输入、最小输入与特殊输入。检查结果不符时，记录每一步变量值，找出首次偏离预期的位置。调试是定位和修正错误，不是不断更改答案直到看起来正确。本课使用伪代码，不要求安装编程软件。')],[('S=1+2+…+n=n(n+1)/2','正整数n，可与循环结果互检')],[ex('用循环求1到4之和，累加器依次是多少？','初值S=0|加入1、2、3、4后为1、3、6、10','10'),ex('为什么循环变量一直等于1会出问题？','若条件为i≤n，且n≥1|不更新i会使条件一直满足','循环可能无法终止')],['手工运行伪代码','变量记录表、笔','设S=0，i=1|当i≤5时计算S=S+i|再令i=i+1并重复|记录每一步i和S','运行轨迹帮助检验更新顺序与停止条件。','仅处理示例数字，不使用个人敏感数据。'],[mc('选择不同路径通常使用什么结构？','顺序|分支|循环|注释',1,'分支根据条件决定执行路径。'),mc('累加求和的初始S通常设为多少？','0|1|n|未知',0,'0是加法的起始累加值。'),mc('下列哪项有助于循环结束？','删除所有条件|不更新变量|设置可达到的终止条件|隐藏错误',2,'循环需有可达到的终止条件和正确更新。'),mc('较合理的测试方法是？','只试一次|只试最大值|不看中间步骤|包含普通与边界输入',3,'边界输入常能暴露遗漏。'),sh('求1到5之和是多少？','15。','1+2+3+4+5=15，可用5×6÷2验证。'),sh('变量追踪表有什么作用？','记录每一步状态，定位首次错误。','能区分初始化、条件、更新等不同错误来源。')],'algorithm',['流程图','循环','调试','循环不等于无条件无限重复。','算法可以先用纸笔表达。','一次正确结果不能证明所有输入都正确。']))
c.append(unit('coding',2,'数组、查找与数据组织','成绩存在列表里，怎样准确找到需要的一项？',[
('列表与索引','列表按顺序保存多个数据，索引用于定位元素。不同语言可能从0或1计数，本课模型从0开始：三个元素的索引是0、1、2。索引表示位置，不是元素本身的数值。访问不存在的位置应判为越界，不能直接当成0。'),('顺序查找','顺序查找从一端依次比较目标与元素，找到后可以停止；全部比较仍未找到，应明确返回“未找到”。对于长度n的无序列表，最坏需要比较n次。若存在重复值，应事先说明要返回第一个位置、全部位置还是出现次数。'),('有序数据与二分思想','有序列表可以用二分思想：先看中间元素，再缩小到可能包含目标的一半区间。二分查找的前提是数据已按确定顺序排列。数据的存储方式应服务于问题，不能只根据列表长度判断哪种方法总是最快。')],[('索引范围：0到n−1','本课约定从0开始'),('顺序查找最坏比较n次','逐项查找长度n的列表')],[ex('列表[7,2,9]中索引1对应什么？','本课从0开始计数|索引0是7，索引1是2','2'),ex('在[4,8,3,6]中顺序查找3，需要比较几次？','比较4，不相等|比较8，不相等|比较3，找到','3次')],['比较两种查找','有序和无序数字卡片','打乱8张数字卡做顺序查找|记录比较次数|排序后尝试二分缩小区间|比较方法所需前提','查找策略依赖数据是否有序及任务要求。','使用虚构数据，不公开真实成绩或个人名单。'],[mc('长度5列表从0计数，最大合法索引是多少？','5|6|4|1',2,'合法索引为0、1、2、3、4。'),mc('二分查找通常要求数据怎样？','有序|全部相同|必须字符串|必须恰好10项',0,'需要利用顺序关系排除一半区间。'),mc('目标不存在时，程序应该怎样？','随便返回一项|明确报告未找到|永远循环|自动创造目标',1,'输出约定应包括未找到情况。'),mc('有重复值时，应先明确什么？','电脑颜色|变量字体|屏幕大小|要找第一个还是全部位置',3,'查找任务定义影响返回结果。'),sh('在[1,5,7,9]中顺序查找9需比较几次？','4次。','逐项比较至最后一个元素。'),sh('为何无序列表不能直接套用普通二分查找？','中间元素大小不能确定目标在哪一半。','丢弃一半时可能把目标错误排除。')],'search',['列表','索引','查找','索引与数值不同。','二分查找需要有序前提。','找不到时必须有明确结果。']))
c.append(unit('coding',3,'排序与复杂度直觉','同样把数字排好，为什么有的方法比较次数更多？',[
('排序与保持数据','排序改变元素顺序，使其满足升序或降序要求；不能删除重复项或随意修改数值。判断排序正确，需要同时检查顺序条件和元素是否完整保留。列表已排好、完全逆序、含重复值都是重要测试情况。'),('冒泡排序','冒泡排序反复比较相邻元素，若顺序不对就交换。升序排序的一轮从左向右比较可把较大的元素逐步移向右端。每轮可以缩短尚未确定的范围；若某一完整轮没有交换，可以提前结束。'),('增长趋势与条件','最坏情况下，基础冒泡排序比较次数为n(n−1)/2，随规模近似平方增长。复杂度讨论关注输入规模增大时工作量的变化，而非某台设备的一次计时。比较次数、交换次数和真实耗时不同，不能相互混用。')],[('最坏比较次数=n(n−1)/2','本课标准逐轮缩短范围的冒泡排序'),('n翻倍，平方型工作量约变为4倍','渐近直觉，不是每次计时严格4倍')],[ex('对[3,1,2]做从左到右的一轮升序冒泡，结果是什么？','3与1交换成[1,3,2]|3与2交换成[1,2,3]','[1,2,3]'),ex('5个元素基础冒泡排序最坏比较几次？','各轮比较4、3、2、1次|相加为10','10次')],['数字卡片冒泡排序','5张数字卡、记录表','打乱数字卡|每次只比较相邻两张|需要时交换并记录次数|每轮结束标出已确定位置','局部比较与交换重复执行，可以完成全局排序。','动画每步用于理解算法，不代表计算机真实运行速度。'],[mc('升序冒泡时何时交换相邻元素？','左边小于右边|左边大于右边|两者始终相等|每次都必须交换',1,'相邻顺序相反时交换。'),mc('排序应该保持什么不变？','元素及其出现次数|原位置|比较次数|列表必须无重复',0,'排序只调整顺序，不增删或改变原始元素。'),mc('4个元素最坏比较次数为多少？','4|8|6|16',2,'3+2+1=6。'),mc('复杂度主要研究什么？','程序颜色|屏幕帧率|文件名称|工作量随输入规模如何增长',3,'复杂度关注规模与资源需求的关系。'),sh('[2,1,3]做一轮升序冒泡，结果是什么？','[1,2,3]。','先交换2与1，再比较2与3无需交换。'),sh('为什么一次计时不能直接证明算法更优？','计时受设备、输入、系统状态等影响。','应比较适用条件、规模和多种输入，并区分理论工作量与实际耗时。')],'sort',['排序','冒泡','复杂度','排序不能丢失重复元素。','比较次数不同于交换次数。','动画速度不等于算法真实运行速度。']))
c.append(unit('coding',4,'模块化与小项目设计','怎样让一个练习程序既能出题，也能可靠地判分？',[
('输入、处理与输出','先把需求写清楚：输入是什么、处理规则是什么、输出需要说明什么。制作加法练习器时，题目、答案、用户输入、评分结果是不同的数据。空输入不能当成数字0；异常输入应提示修改，而不是直接显示正确。'),('拆分与复用','把生成题目、读取答案、判定结果、显示解析拆成不同模块，每个模块承担清晰任务。这样能分别测试并复用，避免修改显示文字时改变评分规则。复杂设计模式不是本阶段的记忆重点，先练习合理分工与简单接口。'),('数据与责任','练习记录应尽量保存在本机，只收集完成任务必需的数据。分享作品前，移除真实姓名、联系方式与个人成绩。程序应说明自动评分能判断什么；开放性解释题不应仅凭关键词匹配就宣称给出可靠成绩。')],[('输入 → 校验 → 处理 → 输出','校验缺失会影响后续判断')],[ex('加法题答案是0，输入框为空，能否判正确？','空输入并不表示数字0|应先检查是否填写|再转换为数字比较','不能，应先要求填写答案'),ex('把“出题”和“判分”写成两个模块有什么好处？','可以独立测试每个模块|不同题型可复用显示与记录逻辑','便于维护、测试与复用')],['纸上设计练习器','流程卡、界面草图','画出题目和作答区域|定义正常、空白、非数字三类输入|分别写出处理路径|与同伴按流程试运行','先处理输入合法性，再比较答案并解释结果。','不收集无关个人信息；开放题采用明确参考答案和自评。'],[mc('作答框为空时，应先怎样？','当作0|当作满分|提示填写|删除题目',2,'应校验输入，而非隐式当成某个数值。'),mc('模块化的主要目的是什么？','拆分清晰职责以便测试复用|尽量增加代码行数|隐藏错误|禁止修改',0,'合理拆分降低耦合并方便独立检验。'),mc('分享学习项目时更合适的做法是？','公开真实成绩名单|移除不必要个人信息|上传全部浏览记录|要求家庭住址',1,'遵守数据最小化原则。'),mc('开放题自动评分应如何说明？','宣称永不出错|只匹配一个词就给满分|无需解释标准|明确能力边界和评价标准',3,'开放题判断复杂，应如实说明评价依据。'),sh('为练习器列出两种边界输入。','空输入、非数字输入等。','也可考虑负数、很大的数或带单位的字符串，并说明规则。'),sh('把项目拆成至少三个模块。','出题、输入校验、判分、解析显示。','各模块输入输出清楚，并能分别测试。')],'workflow',['模块化','项目','数据','空字符串不等于用户确实输入0。','模块越多不一定设计越好。','开放题不能凭简单关键词匹配宣称可靠自动评分。']))
(OUT/'coding.json').write_text(json.dumps(dict(subject='coding',edition='九年级信息科技与编程拓展',editionNote='使用伪代码和纸上算法，不绑定某一版信息科技教材，也不要求安装开发工具。',sources=[],chapters=c),ensure_ascii=False,indent=2))
